#include "PluginEditor.h"
RealityBridgeEditor::RealityBridgeEditor(RealityBridgeProcessor&p):AudioProcessorEditor(&p),p_(p){title_.setText("REALITY BRIDGE // NATIVE STRING CORE",juce::dontSendNotification);title_.setJustificationType(juce::Justification::centred);addAndMakeVisible(title_);setSize(540,180);}void RealityBridgeEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff030507));g.setColour(juce::Colour(0xff74ffd2));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(12),18,2);g.setColour(juce::Colours::white.withAlpha(.7f));g.setFont(14);g.drawFittedText("MIDI Note On excites the same Karplus–Strong core used by the native library. Automate damping, brightness, pick position, body, resonance and output in your host.",24,72,getWidth()-48,70,juce::Justification::centred,3);}void RealityBridgeEditor::resized(){title_.setBounds(20,20,getWidth()-40,36);}
